import {installListFilters,clearListFilters,matchesFilters} from './filters.mjs';
import {evidenceFields,bindEvidence,evidenceMarkup,encouragementFields,bindEncouragement} from './personalize.mjs';
import {createGamesUI} from './game-ui.mjs';
import {levelLabels,CATEGORIES,assessmentSummary,archiveCriterion} from './learning.mjs';
import {isPrimary,isParent,can,permittedRoutes,validPhoto} from './family.mjs';
import {createFamilyUI} from './family-ui.mjs';
import {usernameEmail,publicConfig} from './identity.mjs';
import {blank,today,evaluate,earned,pointDetails,journeyPoints,balance,redeem,submitQuiz,weekStart,validate,requestError,submissionStatus,submissionWindow,criterionLimit,isGameAttempt,deduct,resetPoints} from './core.mjs';
const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),uid=()=>Array.from(crypto.getRandomValues(new Uint8Array(16)),x=>x.toString(16).padStart(2,'0')).join('');
let state=blank(),revision=0,session=null,mode='',selected='',busy=false,membership=null,pointRequests=[],members=[],sharedConfig=false;
const isChild=()=>membership?.role==='child';
const isAdmin=()=>isPrimary(membership);
const canPoints=()=>can(membership,'reset_points')||can(membership,'deduct_points');
let familySuggestions=[],demoReturn=null,assessmentDay='';
let config=null;try{config=JSON.parse(localStorage.getItem('kids-config')||'null')}catch{}
try{const r=await fetch('./config.json',{cache:'no-store'});const c=await r.json();if(c.url){config=publicConfig(c);sharedConfig=true;}}catch{}
const app=$('#app'),note=(t,kind='error')=>{const box=$('#notice');box.textContent=t;box.className=kind;box.setAttribute('role',kind==='success'?'status':'alert');if(t){if($('#modal').open){let hint=$('#modalNotice');if(!hint){hint=document.createElement('p');hint.id='modalNotice';$('#modalBody').prepend(hint)}hint.textContent=t;hint.className='form-message '+kind;$('#modal').scrollTop=0;}requestAnimationFrame(()=>window.scrollTo({top:0,behavior:'smooth'}));}},options=()=>state.children.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('');
const input=(name,label,value='',type='text',extra='')=>`<label><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${extra} required></label>`;
const pick=()=>`<label><span>الطفل</span><select name="child" required>${options()}</select></label>`;
function modal(html){$('#modalBody').innerHTML=html;$('#modal').showModal()}
$('#closeModal').onclick=()=>$('#modal').close();
async function request(path,body,method='POST',token=session?.access_token){const r=await fetch(config.url+path,{method,headers:{apikey:config.key,'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},...(body!==undefined?{body:JSON.stringify(body)}:{})});const data=await r.json().catch(()=>null);if(!r.ok){const error=new Error(requestError(r.status,data,path));error.status=r.status;throw error};return data;}
async function refreshToken(){if(!session)return; if(session.expires_at*1000<Date.now()+60000){session=await request('/auth/v1/token?grant_type=refresh_token',{refresh_token:session.refresh_token},'POST',null);session.expires_at=Math.floor(Date.now()/1000)+session.expires_in;sessionStorage.setItem('kids-session',JSON.stringify(session));}}
async function load(){const prior=pointRequests.filter(r=>r.status==='pending').map(r=>r.id);await refreshToken();membership=await request('/rest/v1/rpc/my_membership',{});const result=await request('/rest/v1/rpc/load_family',{});state=result.data||blank();revision=result.revision;validate(state);pointRequests=await request('/rest/v1/point_requests?select=*&order=created_at.desc',undefined,'GET');if(isChild()){selected=membership.child_id;if(pointRequests.some(r=>r.status==='approved'&&prior.includes(r.id)))features.celebrate();}}
async function save(next){if(!isParent(membership))throw Error('التعديل لولي الأمر فقط');validate(next);if(mode==='cloud'){await refreshToken();const r=await request('/rest/v1/rpc/save_family',{p_data:next,p_revision:revision});revision=r;}state=next;render();}
async function mutate(fn){if(busy)return;busy=true;try{const next=structuredClone(state);fn(next);await save(next);$('#modal').close();$('#modalBody').replaceChildren();const dailyForm=$('#dailyForm');if(dailyForm){dailyForm.querySelectorAll('select').forEach(e=>e.value='');dailyForm.querySelectorAll('input,textarea').forEach(e=>e.value='')}note(mode==='demo'?'تم الحفظ في التجربة المؤقتة بنجاح.':'تم الحفظ والمزامنة بنجاح.','success');}catch(e){note(e.message)}finally{busy=false}}
function setup(){app.innerHTML=`<div class="hero"><img class="hero-logo" src="logo.svg" alt="شعار عائلة أبو غازي" width="150" height="82"><h2>كل يوم فرصة لإنجاز جديد</h2><p>مساحة هادئة لمتابعة التعلم والعادات واللحظات الجميلة.</p></div><div class="grid"><div class="card"><h2>ربط مساحة العائلة</h2><p class="muted">إعداد تقني أولي لمدير الموقع. انشر رابط المشروع ومفتاحه العام مرة واحدة في إعدادات GitHub لتظهر شاشة الدخول على جميع الأجهزة دون إعادة الربط.</p><form id="config">${input('url','رابط المشروع',config?.url||'','url')}${input('key','المفتاح العام Publishable أو anon',config?.key||'')}<button>حفظ على هذا الجهاز</button></form><p>لجميع الأجهزة: أضف SUPABASE_URL وSUPABASE_PUBLISHABLE_KEY إلى متغيرات GitHub Actions ثم أعد النشر. <a href="https://github.com/ashtayyat/kids/blob/main/UPGRADE_AR.md">خطوات التفعيل</a></p><p><a href="https://github.com/ashtayyat/kids#readme" target="_blank" rel="noopener">تعليمات إعداد قاعدة البيانات</a></p></div><div class="card"><h2>استكشف قبل البدء ✨</h2><p>تجربة مؤقتة ببيانات افتراضية، لا تتزامن ولا تُحفظ بعد إغلاق الصفحة.</p><button id="demo">بدء التجربة</button></div></div>`;$('#config').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),url=f.get('url').replace(/\/$/,'');if(!/^https:\/\/[a-z0-9-]+\.supabase\.co$/.test(url))return note('استخدم رابط مشروع Supabase بصيغة https://example.supabase.co');const key=f.get('key').trim();if(key.startsWith('sb_secret_'))return note('لا تستخدم المفتاح السري. أدخل المفتاح العام فقط.');try{config=publicConfig({url,key});localStorage.setItem('kids-config',JSON.stringify(config));login()}catch(e){note(e.message)}};$('#demo').onclick=startDemo;}
function login(){app.innerHTML=`<div class="hero"><img class="hero-logo" src="logo.svg" alt="شعار عائلة أبو غازي" width="150" height="82"><h2>أهلًا بعائلتنا</h2><p>كل إنجاز يبدأ بمحاولة. سجّل الدخول إلى مساحتك الخاصة.</p></div><div class="card login-card"><h2>تسجيل الدخول</h2><form id="login">${input('username','اسم المستخدم أو بريد ولي الأمر','','text','autocomplete="username"')}${input('password','كلمة المرور','','password','autocomplete="current-password"')}<button>دخول إلى مساحتي ←</button></form><p class="muted">حساب الطفل ينشئه ولي الأمر من صفحة «الحسابات». لا يحتاج الطفل إلى بريد إلكتروني.</p>${!sharedConfig?'<button id="reconfig" class="secondary">إعداد مدير الموقع</button>':''}<p><button id="loginDemo" class="secondary">تجربة آمنة دون حفظ</button></p></div>`;$('#loginDemo').onclick=startDemo;if($('#reconfig'))$('#reconfig').onclick=setup;$('#login').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const f=new FormData(e.target),name=f.get('username').trim();const email=name.includes('@')?name:await usernameEmail(name);session=await request('/auth/v1/token?grant_type=password',{email,password:f.get('password')},'POST',null);session.expires_at=Math.floor(Date.now()/1000)+session.expires_in;sessionStorage.setItem('kids-session',JSON.stringify(session));await load();mode='cloud';location.hash='home';render();note('أهلًا '+membership.display_name,'success');}catch(e){note(e.message)}finally{b.disabled=false}};}
function quickButtons(child='',criterion=''){return isParent(membership)?`<div class="row"><button class="secondary" data-quick-child="${esc(child)}" data-quick-criterion="${esc(criterion)}" data-quick-action="add">+ إضافة نقاط</button>${can(membership,'deduct_points')?`<button class="secondary" data-quick-child="${esc(child)}" data-quick-criterion="${esc(criterion)}" data-quick-action="deduct">− خصم نقاط</button>`:''}</div>`:'';}
function quickPointsForm(child,criterion,action){if(!isParent(membership))return;const title={add:'إضافة نقاط تشجيعية',deduct:'خصم نقاط',reset:'تصفير جميع نقاط الطفل'}[action];modal(`<h2>${title}</h2><form id="quickPointsForm">${pick()}${action==='reset'?'<p>ستُؤرشف جميع نقاط الطفل وخصوماته واستبدالاته وطلبات الإنجاز بعملية واحدة، ويصبح رصيده صفرًا. تُلغى طلبات المكافآت والألعاب المعلقة. لا تُحذف الحسابات أو ملفات الأطفال.</p><label>اكتب تصفير للتأكيد<input name="confirmation" required autocomplete="off"></label>':input('amount','عدد النقاط',1,'number','min="1" max="1000"')}<label>السبب<textarea name="reason" required maxlength="300"></textarea></label><button>${action==='reset'?'تأكيد التصفير الكامل':'حفظ العملية'}</button></form>`);const form=$('#quickPointsForm');if(child||selected)form.elements.child.value=child||selected;form.onsubmit=async e=>{e.preventDefault();if(busy)return;const f=new FormData(form);if(action==='reset'&&f.get('confirmation')!=='تصفير')return note('اكتب تصفير للتأكيد');busy=true;form.querySelector('button').disabled=true;try{if(mode==='demo'){const next=structuredClone(state),id=f.get('child');if(action==='add'){const entry=uid();next.attempts.push({id:entry,quiz:'bonus_'+entry,kind:'bonus',child:id,criterion:criterion||null,name:'نقاط تشجيعية',points:+f.get('amount'),correct:0,total:0,note:f.get('reason'),date:today()})}else if(action==='deduct')deduct(next,id,criterion||null,+f.get('amount'),f.get('reason'),uid(),today());else{resetPoints(next,id,null,uid(),today(),f.get('reason'));pointRequests=pointRequests.filter(r=>r.child_id!==id);features.cancelRewardRequests(id)}validate(next);state=next}else{await refreshToken();await request('/rest/v1/rpc/quick_points',{p_child:f.get('child'),p_action:action,p_criterion:action==='reset'?null:criterion||null,p_amount:action==='reset'?0:+f.get('amount'),p_reason:f.get('reason'),p_revision:revision});await load()}$('#modal').close();render();note('تمت العملية وتحديث الرصيد بنجاح.','success')}catch(error){note(error.message)}finally{busy=false;if(form.isConnected)form.querySelector('button').disabled=false}};}
function dailyScheduleForm(){const v=state.submissionSchedule||{enabled:false,start:'16:00',end:'21:00'};modal(`<h2>وقت تعبئة الإنجازات اليومي</h2><p>فترة يومية بتوقيت عمّان، مستقلة عن المؤقت. يجب أن تكون الفترة مفتوحة وألا يكون المؤقت المفعّل قد انتهى. إذا كان الإغلاق قبل الفتح تمتد الفترة بعد منتصف الليل.</p><form id="dailySchedule"><label class="check-row"><input type="checkbox" name="enabled" ${v.enabled?'checked':''}>تفعيل فترة التعبئة اليومية</label>${input('start','وقت الفتح',v.start,'time')}${input('end','وقت الإغلاق',v.end,'time')}<button>حفظ وقت التعبئة اليومي</button></form>`);$('#dailySchedule').onsubmit=async e=>{e.preventDefault();if(busy)return;const f=new FormData(e.target);if(f.get('start')===f.get('end'))return note('حدد وقت فتح وإغلاق مختلفين');busy=true;try{if(mode==='demo')state.submissionSchedule={enabled:f.has('enabled'),start:f.get('start'),end:f.get('end')};else{await refreshToken();await request('/rest/v1/rpc/set_submission_schedule',{p_enabled:f.has('enabled'),p_start:f.get('start'),p_end:f.get('end'),p_revision:revision});await load()}$('#modal').close();render();note('تم حفظ وقت التعبئة اليومي مع الإبقاء على المؤقت.','success')}catch(error){note(error.message)}finally{busy=false}};}
function submissionControl(id=null){const c=id?state.criteria.find(c=>c.id===id):null;if(id&&!c)return;const expiry=c?c.submission_expires_at:state.submissionSettings?.expires_at;modal(`<h2>${c?'مؤقت إرسال: '+esc(c.name):'مؤقت إرسال جميع الإنجازات'}</h2><p>تبدأ المدة عند الضغط على بدء المؤقت، وتستمر بين الأجهزة وبعد إغلاق الصفحة. إذا وُجد مؤقت عام وخاص يطبق الأسبق. منع أطفال محددين متاح داخل تعديل المعيار.</p>${expiry?`<p>نهاية المؤقت: ${esc(new Date(expiry).toLocaleString('ar-JO',{timeZone:'Asia/Amman'}))} بتوقيت عمّان</p>`:'<p>لا يوجد مؤقت مفعّل لهذا النطاق.</p>'}<form id="submissionControl">${input('minutes','مدة المؤقت بالدقائق',c?.timer_minutes||state.submissionSettings?.minutes||30,'number','min="1" max="1440"')}<div class="row"><button name="action" value="start">بدء / إعادة بدء المؤقت</button><button name="action" value="stop" class="danger">إنهاء الوقت الآن</button><button name="action" value="clear" class="secondary">إلغاء القيد الزمني</button></div></form>`);$('#submissionControl').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;try{const f=new FormData(e.target),action=e.submitter.value,minutes=+f.get('minutes'),expires=action==='clear'?null:new Date(Date.now()+(action==='start'?minutes*60000:0)).toISOString();if(mode==='demo'){if(c){c.submission_expires_at=expires;c.timer_minutes=minutes;delete c.submission_cutoff}else state.submissionSettings={expires_at:expires,minutes}}else{await refreshToken();await request('/rest/v1/rpc/set_submission_timer',{p_criterion:id,p_minutes:minutes,p_action:action,p_revision:revision});await load()}$('#modal').close();render();note(action==='start'?'بدأ المؤقت.':action==='stop'?'انتهى وقت الإرسال.':'أُلغي القيد الزمني لهذا النطاق.','success')}catch(error){note(error.message)}finally{busy=false}};}
function bindQuickActions(){document.querySelectorAll('[data-daily-schedule]').forEach(b=>b.onclick=dailyScheduleForm);document.querySelectorAll('[data-quick-action]').forEach(b=>b.onclick=()=>quickPointsForm(b.dataset.quickChild,b.dataset.quickCriterion,b.dataset.quickAction));document.querySelectorAll('[data-submission-control]').forEach(b=>b.onclick=()=>submissionControl(b.dataset.submissionControl||null));}
function childCard(c){const week=journeyPoints(state,c.id,weekStart(),today()),assessment=assessmentSummary(state,c.id,today(),pointRequests),original=[...state.evaluations,...state.attempts].filter(r=>r.child===c.id).reduce((sum,r)=>sum+r.points,0),deductions=-(state.adjustments||[]).filter(r=>r.child===c.id).reduce((sum,r)=>sum+r.points,0),exchanged=state.redemptions.filter(r=>r.child===c.id).reduce((sum,r)=>sum+r.cost,0);return `<article class="card"><div class="row between"><span class="avatar">${features.avatar(c)}</span><span class="score">⭐ ${balance(state,c.id)} نقطة صافية</span></div><h3>${esc(c.name)}</h3><p class="muted">هدف الأسبوع: ${week} من ${c.goal} نقطة</p><progress value="${Math.min(week,c.goal)}" max="${c.goal}" aria-label="تقدم هدف الأسبوع"></progress><section class="points-summary" aria-label="ملخص نقاط ${esc(c.name)}"><h4>ملخص النقاط</h4><dl><div><dt>النقاط الأصلية المكتسبة</dt><dd>${original} نقطة</dd></div>${deductions?`<div><dt>الخصومات المسجلة</dt><dd>− ${deductions} نقطة</dd></div>`:''}<div><dt>النقاط المستبدلة بمكافآت</dt><dd>${exchanged} نقطة</dd></div><div class="points-remaining"><dt>الرصيد المتبقي المتاح</dt><dd>${balance(state,c.id)} نقطة</dd></div></dl><small>إجمالي السجلات الحالية · الاستبدالات المعتمدة فقط</small></section><p class="muted">تقييم اليوم: ${assessment.assessed} من ${assessment.total} معيارًا<br>لم يُقيّم بعد: ${assessment.missing.length} معيارًا · حتى ${assessment.remainingMax} نقطة ممكنة</p>${quickButtons(c.id)}<button data-profile="${esc(c.id)}" class="secondary">مساحة الطفل ←</button>${features.journey(c)}</article>`;}
function home(){app.innerHTML=`<div class="hero"><img class="hero-logo" src="logo.svg" alt="شعار عائلة أبو غازي" width="150" height="82"><h2>نحتفل بالمحاولة، ونكبر بالاستمرار</h2><p>تعلم، عادة جميلة، أو مساعدة صغيرة… كل خطوة تستحق التقدير.</p><a class="button secondary" href="#daily">لنبدأ إنجازات اليوم ←</a></div><div class="row between"><h2>مساحات أطفالي</h2>${isParent(membership)?'<button id="addChild">+ إضافة طفل</button>':''}</div>${state.children.length?`<div class="grid">${state.children.map(childCard).join('')}</div>`:'<div class="card empty"><div class="icon">🌼</div><h3>تبدأ الحكاية بخطوة</h3><p>أضف أطفالك من لوحة ولي الأمر، ثم خصّص مهامهم.</p></div>'}<div class="grid"><div class="card">☀ <b>عادات يومية</b><p class="muted">التقييم يشجع المحاولة والاستقلالية.</p></div><div class="card">✎ <b>تعلم باطمئنان</b><p class="muted">اختبارات قصيرة تناسب مستوى كل طفل.</p></div><div class="card">🎁 <b>لحظات نستحقها</b><p class="muted">مكافآت يختارها ولي الأمر مع العائلة.</p></div></div>`;if($('#addChild'))$('#addChild').onclick=()=>childForm();}
function childForm(id){return features.childForm(id)}
function assessmentPanel(child){return `<section class="card assessment-summary"><h2>المعايير التي لم تُقيّم بعد — ${esc(child.name)}</h2><label>تاريخ المتابعة<input id="assessmentDate" type="date" value="${assessmentDay||today()}" max="${today()}"></label><p class="muted">بحسب المعايير الحالية المطبّقة على هذا الطفل. التقييم بصفر يُعد تقييمًا مكتملًا، والطلب المعلّق يبقى غير معتمد حتى الموافقة.</p><div id="assessmentDetails" aria-live="polite"></div></section>`}
function bindAssessmentPanel(child){const date=$('#assessmentDate'),details=$('#assessmentDetails');if(!date||!details)return;const draw=()=>{if(!date.value){details.textContent='اختر تاريخ المتابعة';return}const a=assessmentSummary(state,child.id,date.value,pointRequests);details.innerHTML=`<div class="grid"><div><b>المعايير المُقيّمة</b><p>${a.assessed} من ${a.total}</p></div><div><b>النقاط المعتمدة لهذه المعايير</b><p>${a.earned} نقطة</p></div><div><b>نقاط ممكنة لم تُقيّم بعد</b><p>حتى ${a.remainingMax} من ${a.dailyMax} نقطة يومية ممكنة</p></div></div>${a.missing.length?`<ul class="assessment-list">${a.missing.map(c=>`<li><div><b>${esc(c.name)}</b><span class="badge">${c.requestStatus==='pending'?'بانتظار موافقة ولي الأمر':c.requestStatus==='rejected'?'طلب أعيد للمراجعة':'لم يُسجل تقييم'}</span></div><span>حتى ${c.maxPoints} نقطة ممكنة</span></li>`).join('')}</ul>`:'<p class="success-text">تم تقييم جميع المعايير لهذا التاريخ ✓</p>'}<p class="muted">النقاط الممكنة ليست رصيدًا مكتسبًا ولا تُخصم من الطفل. الاختبارات والمكافآت والخصومات لا تدخل في هذا الملخص.</p>`};date.onchange=()=>{assessmentDay=date.value;draw()};draw()}
function profile(id){selected=id;const c=state.children.find(x=>x.id===id);if(!c)return;const records=[...(state.adjustments||[]),...state.evaluations.map(e=>({...e,name:state.criteria.find(x=>x.id===e.criterion)?.name||'معيار سابق'})),...state.attempts].filter(e=>e.child===id).sort((a,b)=>b.date.localeCompare(a.date));app.innerHTML=`<div class="hero"><span class="plant">${features.avatar(c)}</span><h2>مرحبًا ${esc(c.name)}!</h2>${isParent(membership)&&can(membership,'reset_points')?`<button class="danger" data-quick-action="reset" data-quick-child="${esc(id)}" data-quick-criterion="">تصفير جميع نقاط الطفل</button>`:''}<p>أنت تتقدم مع كل محاولة. لنحتفل بما أنجزته اليوم.</p></div><div class="grid">${childCard(c)}<div class="card"><h3>رحلتي هذا الأسبوع</h3><div class="number">${journeyPoints(state,id,weekStart(),today())} ⭐</div><p>نقاط الأسبوع بعد الخصومات والاستبدالات المعتمدة خلال هذا الأسبوع. لا ينخفض مؤشر الرحلة عن صفر.</p></div></div>${assessmentPanel(c)}<div class="card" id="profileLedger" data-filter-scope="${esc(id)}"><h2>دفتر إنجازاتي</h2>${quickButtons(id)}${isParent(membership)?`<section class="points-summary"><h3>الخصومات وأسبابها</h3>${(state.adjustments||[]).filter(r=>r.child===id).slice().reverse().map(r=>`<article class="task"><b>${r.points} نقطة · ${esc(r.date)}</b><p>سبب الخصم: ${esc(r.note||'لم يُسجل سبب')}</p></article>`).join('')||'<p>لا توجد خصومات مسجلة لهذا الطفل.</p>'}</section>`:''}${records.length?records.map(r=>`<article data-filter-item data-filter-date="${esc(r.date)}"><p>${esc(r.date)} · ${esc(r.name)} · ⭐ ${r.points}<br><small>${esc(r.note||'أحسنت المحاولة!')}</small></p>${evidenceMarkup(r.evidence,esc)}</article>`).join(''):'ابدأ أول مهمة لتظهر إنجازاتك هنا.'}</div>`;bindProfiles();bindAssessmentPanel(c);installListFilters($('#profileLedger'),{esc});}
function daily(){app.innerHTML=`<div class="card"><h2>خطوات اليوم ☀</h2>${quickButtons()}<button type="button" data-submission-control="" class="secondary">مؤقت الإنجازات</button><button data-daily-schedule class="secondary">وقت التعبئة اليومي</button><div class="toolbar">${pick()}${input('date','تاريخ التقييم',today(),'date','max="'+today()+'"')}</div><form id="dailyForm"></form></div>`;const child=$('[name=child]'),date=$('[name=date]');if(selected)child.value=selected;let readers=new Map();const draw=()=>{selected=child.value;$('#dailyForm').innerHTML=state.criteria.filter(c=>!c.archived&&(!c.assigned_child||c.assigned_child===child.value)).map(c=>{const e=state.evaluations.find(e=>e.child===child.value&&e.date===date.value&&e.criterion===c.id);return `<div class="task" data-proof-criterion="${esc(c.id)}"><b>${esc(c.name)}</b><label>مستوى الإنجاز<select name="level-${c.id}"><option value="">لم يُقيّم بعد</option>${levelLabels(c).map((t,i)=>`<option value="${i}" ${e?.level===i?'selected':''}>${t} (${c.points[i]} نقطة)</option>`).join('')}</select></label><label>ملاحظة إيجابية<input maxlength="300" name="note-${c.id}" value="${esc(e?.note||'')}" placeholder="أعجبني إصرارك اليوم…"></label>${evidenceFields()}</div>`}).join('')+`<button ${!child.value?'disabled':''}>حفظ تقييم اليوم</button>`;readers=new Map();document.querySelectorAll('[data-proof-criterion]').forEach(root=>{const id=root.dataset.proofCriterion,old=state.evaluations.find(e=>e.child===child.value&&e.date===date.value&&e.criterion===id);readers.set(id,bindEvidence(root,old?.evidence,note))})};child.onchange=draw;date.onchange=draw;draw();$('#dailyForm').onsubmit=async e=>{e.preventDefault();if(!date.value||date.value>today())return note('اختر تاريخًا لا يتجاوز اليوم');const f=new FormData(e.target),childId=child.value,day=date.value;try{const proofs=Object.fromEntries(await Promise.all([...readers].filter(([id])=>f.get('level-'+id)!=='').map(async([id,read])=>[id,await read()])));await mutate(s=>{for(const c of s.criteria){const level=f.get('level-'+c.id);if(level!==null&&level!=='')evaluate(s,{child:childId,criterion:c.id,date:day,level:+level,note:f.get('note-'+c.id),evidence:proofs[c.id],occurrence:s.evaluations.find(e=>e.child===childId&&e.criterion===c.id&&e.date===day)?.occurrence||1});}})}catch(error){note(error.message)}};}
function settings(criteriaOnly=false){const general=assessmentSummary(state,null,today());app.innerHTML=`<div class="row between"><h2>معايير العائلة</h2><button id="criterion">+ إضافة معيار</button><button data-submission-control="" class="secondary">مؤقت الإنجازات</button><button data-daily-schedule class="secondary">وقت التعبئة اليومي</button>${quickButtons()}</div><section class="card assessment-summary"><h2>مجموع نقاط التقييم</h2><div class="grid"><div><span>الحد الأقصى للمعايير العامة يوميًا</span><div class="number">${general.dailyMax} نقطة</div><small>${general.total} معيارًا عامًا</small></div><div><span>الحد الأقصى خلال ٧ أيام</span><div class="number">${general.weeklyMax} نقطة</div></div></div><p class="muted">نجمع أعلى نقاط ممكنة لكل معيار، ولا نجمع خياراته الثلاثة. يتحدّث المجموع تلقائيًا عند إضافة معيار أو تعديل نقاطه. هذا مجموع ممكن وفق المعايير الحالية، ولا يشمل نقاط الاختبارات أو الخصومات، والهدف الأسبوعي يُحدد في ملف الطفل.</p>${state.children.length?`<div class="table-wrap"><table><thead><tr><th>الطفل</th><th>عدد المعايير</th><th>أقصى نقاط يومية</th><th>أقصى نقاط خلال ٧ أيام</th></tr></thead><tbody>${state.children.map(c=>{const a=assessmentSummary(state,c.id,today());return `<tr><td>${esc(c.name)}</td><td>${a.total}</td><td>${a.dailyMax}</td><td>${a.weeklyMax}</td></tr>`}).join('')}</tbody></table></div><p class="muted">المهام المخصصة تُضاف إلى مجموع الطفل المعني فقط.</p>`:''}</section><div class="grid">${state.criteria.filter(c=>!c.archived).map(c=>`<div class="card" data-filter-item><h3>${esc(c.name)}</h3><p>النقاط: ${c.points.join(' / ')}</p><p>الحد اليومي: ${criterionLimit(c)} مرة</p><p>المؤقت: ${esc((c.submission_expires_at||state.submissionSettings?.expires_at)?new Date(c.submission_expires_at||state.submissionSettings.expires_at).toLocaleString('ar-JO',{timeZone:'Asia/Amman'}):'غير مفعّل')} · الممنوعون: ${(c.blocked_children||[]).length}</p><button data-submission-control="${c.id}" class="secondary">مؤقت الإرسال</button><details class="edit-menu"><summary class="button secondary">تعديل</summary>${quickButtons('',c.id)}<button data-criterion="${c.id}" class="secondary">تعديل المعيار والمحاور</button> <button data-convert-criterion="${c.id}" class="secondary">تحويل إلى بند خصم</button> <button data-delete-criterion="${c.id}" class="danger">حذف المعيار</button></details></div>`).join('')}</div>${criteriaOnly?'':`<div class="card"><h2>بياناتك بين يديك</h2><p>النسخة الاحتياطية تتضمن بيانات الأطفال؛ احفظها في مكان خاص. الاستيراد يستبدل بيانات حسابك بعد التحقق.</p><div class="row"><button id="export">تصدير نسخة احتياطية</button><label class="button secondary">استيراد نسخة<input id="import" type="file" accept="application/json" hidden></label><button id="sync" class="secondary">مزامنة الآن</button></div><p class="muted">${mode==='demo'?'وضع التجربة: لا يوجد حفظ دائم.':'المزامنة تتم عند فتح الموقع، وبعد كل تعديل، وعند الضغط على مزامنة. الجلسة محفوظة في علامة التبويب حتى إغلاقها.'}</p></div>`}`;$('#criterion').onclick=()=>criterionForm();document.querySelectorAll('[data-criterion]').forEach(b=>b.onclick=()=>criterionForm(b.dataset.criterion));document.querySelectorAll('[data-delete-criterion]').forEach(b=>b.onclick=()=>deleteCriterionForm(b.dataset.deleteCriterion));document.querySelectorAll('[data-convert-criterion]').forEach(b=>b.onclick=()=>criterionDeduction(b.dataset.convertCriterion));if(criteriaOnly)return;$('#export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='family-backup-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('#import').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>2000000)throw Error('الملف يتجاوز ٢ ميغابايت');const data=validate(JSON.parse(await file.text()));if(confirm('استبدال جميع بيانات الحساب بهذه النسخة؟ صدّر نسخة حالية أولًا.'))await mutate(s=>{for(const key of Object.keys(s))delete s[key];Object.assign(s,data)})}catch(e){note('تعذر الاستيراد: '+e.message)}};$('#sync').onclick=async()=>{try{if(mode==='cloud')await load();render();note('تم تحديث البيانات.','success')}catch(e){note(e.message)}};}
function deleteCriterionForm(id){if(!isParent(membership))return;const c=state.criteria.find(c=>c.id===id&&!c.archived);if(!c)return;modal(`<h2>حذف المعيار: ${esc(c.name)}</h2><p>سيُحذف المعيار من التقييمات الجديدة ومن مجموع النقاط الممكنة والمعايير غير المُقيّمة. تبقى تقييماته السابقة وأسماؤها ونقاط الأطفال في السجل والتقارير. تُغلق طلباته المعلّقة دون منح نقاط.</p><form id="deleteCriterionForm"><button class="danger">تأكيد حذف المعيار</button></form>`);$('#deleteCriterionForm').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;e.target.querySelector('button').disabled=true;try{if(mode==='demo'){archiveCriterion(state,id);pointRequests.filter(r=>r.criterion_id===id&&r.status==='pending').forEach(r=>{r.status='rejected';r.review_note='تم حذف المعيار من التقييم الجديد'})}else{await refreshToken();await request('/rest/v1/rpc/delete_criterion',{p_criterion:id,p_revision:revision});await load()}$('#modal').close();$('#modalBody').replaceChildren();render();note('تم حذف المعيار من التقييم الجديد مع الاحتفاظ بالسجل والنقاط السابقة.','success')}catch(e){note(e.message)}finally{busy=false;if(e.target.isConnected)e.target.querySelector('button').disabled=false}};}
function criterionDeduction(id){const c=state.criteria.find(c=>c.id===id&&!c.archived);if(!c)return;modal(`<h2>تحويل المعيار إلى بند خصم</h2><p>تُحفظ الإنجازات والنقاط السابقة. لا تُخصم أي نقاط عند إنشاء البند.</p><form id="criterionDeduction">${input('name','اسم بند الخصم',c.name,'text','maxlength="100"')}<label>وصف الحالة<textarea name="description" maxlength="300"></textarea></label>${input('points','نقاط الخصم عند تسجيل الحالة',1,'number','min="1" max="1000"')}<label class="check-row"><input name="archive" type="checkbox" checked> إيقاف معيار الإنجاز عن الاستخدام الجديد</label><button>تأكيد التحويل دون خصم</button></form>`);$('#criterionDeduction').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;try{const f=new FormData(e.target);if(mode==='demo'){if((state.deductionRules||[]).some(r=>r.source_criterion===id&&!r.archived))throw Error('أُضيف بند لهذا المعيار بالفعل');(state.deductionRules??=[]).push({id:uid(),name:f.get('name'),description:f.get('description'),points:+f.get('points'),source_criterion:id});if(f.has('archive')){c.archived=true;pointRequests.filter(r=>r.criterion_id===id&&r.status==='pending').forEach(r=>r.status='rejected')}}else{await refreshToken();await request('/rest/v1/rpc/criterion_to_deduction',{p_criterion:id,p_name:f.get('name'),p_description:f.get('description'),p_points:+f.get('points'),p_archive:f.has('archive'),p_revision:revision});await load()}$('#modal').close();render();note('تم إنشاء بند الخصم مع حفظ النقاط السابقة، دون خصم تلقائي.','success')}catch(error){note(error.message)}finally{busy=false}};}
function criterionForm(id){const c=state.criteria.find(c=>c.id===id)||{name:'',points:[0,2,4]};modal(`<h2>تخصيص المعيار</h2><p>التعديل يطبق على التقييمات التي تحفظ لاحقًا؛ السجلات السابقة تحتفظ بنقاطها.</p><form id="cf">${input('name','اسم المعيار',c.name,'text','maxlength="80"')}${c.points.map((p,i)=>`<fieldset><legend>المحور ${i+1}</legend>${input('label'+i,'اسم المحور '+(i+1),levelLabels(c)[i],'text','maxlength="80"')}${input('p'+i,'نقاط المحور '+(i+1),p,'number','min="0" max="1000"')}</fieldset>`).join('')}<label class="check-row"><input type="checkbox" name="repeat" ${c.allow_repeat?'checked':''}> السماح بأكثر من مرة في اليوم</label>${input('limit','أقصى مرات يوميًا عند السماح بالتكرار',Math.max(2,c.max_per_day||3),'number','min="2" max="20"')}<h3>منع إرسال المعيار</h3>${state.children.map(ch=>`<label class="check-row"><input type="checkbox" name="blocked" value="${esc(ch.id)}" ${(c.blocked_children||[]).includes(ch.id)?'checked':''}>${esc(ch.name)}</label>`).join('')}<button>حفظ المعيار</button></form>`);$('#cf').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);mutate(s=>{const row={...c,id:id||uid(),name:f.get('name').trim(),points:[0,1,2].map(i=>+f.get('p'+i)),labels:[0,1,2].map(i=>f.get('label'+i).trim()),blocked_children:f.getAll('blocked'),allow_repeat:f.has('repeat'),max_per_day:f.has('repeat')?+f.get('limit'):1};if(id)s.criteria[s.criteria.findIndex(x=>x.id===id)]=row;else s.criteria.push(row)})};}
function rewards(){return features.rewards()}
function rewardForm(id){location.hash='newreward'+(id?'?id='+id:'');render()}
function quizzes(){const child=state.children.find(c=>c.id===membership?.child_id);app.innerHTML=`<div class="row between"><h2>الاختبارات والتحديات ✎</h2>${isParent(membership)?'<button id="newQuiz">+ اختبار جديد</button>':''}</div><p class="muted">تحديات تعليمية فردية بلا ترتيب بين الإخوة. تُحتسب محاولة واحدة لكل اختبار يوميًا. التصحيح تلقائي، والنتيجة تحسب من الإجابات على الخادم. هذه أنشطة تدريبية، والحلول موجودة في التطبيق.</p><label>المجال<select id="quizCategory"><option value="">كل المجالات</option>${CATEGORIES.map(c=>`<option>${esc(c)}</option>`).join('')}</select></label><div class="grid" id="quizList"></div><div class="card"><h3>نتائجي والمحاولات المسجلة</h3>${state.attempts.map(a=>`<p>${esc(state.children.find(c=>c.id===a.child)?.name)} · ${esc(a.name)} · ${esc(a.date)} · ${a.correct} / ${a.total} · ${a.points} نقطة</p>`).join('')||'ابدأ تحديًا لتظهر النتيجة هنا.'}</div>`;
 const draw=()=>{const cat=$('#quizCategory').value;$('#quizList').innerHTML=state.quizzes.filter(q=>(!cat||q.category===cat)&&(!child||(!q.min_age||child.age>=q.min_age)&&(!q.max_age||child.age<=q.max_age))).map(q=>`<article class="card"><span class="badge">${esc(q.category||'اختبار دراسي')}</span><h3>${esc(q.name)}</h3><p>${q.questions.length} أسئلة · حتى ${q.points} نقطة</p><p>${q.min_age?'العمر المناسب: '+q.min_age+'–'+(q.max_age||18):'مخصص للأسرة'}</p><button data-quiz="${q.id}">ابدأ التحدي</button>${isParent(membership)?` <button data-edit-quiz="${q.id}" class="secondary">تعديل</button>`:''}</article>`).join('')||'<div class="card">لا يوجد تحدٍّ مناسب في هذا المجال بعد.</div>';document.querySelectorAll('[data-quiz]').forEach(b=>b.onclick=()=>attemptQuiz(b.dataset.quiz));document.querySelectorAll('[data-edit-quiz]').forEach(b=>b.onclick=()=>quizEditor(b.dataset.editQuiz))};$('#quizCategory').onchange=draw;draw();if($('#newQuiz'))$('#newQuiz').onclick=()=>quizEditor();}
function quizEditor(id){if(!isParent(membership))return;const q=state.quizzes.find(q=>q.id===id)||{name:'',points:10,category:'معلومات عامة',questions:[]};modal(`<h2>${id?'تعديل الاختبار':'اختبار جديد'}</h2><form id="qf">${input('name','عنوان الاختبار',q.name,'text','maxlength="100"')}<label>المجال<select name="category">${CATEGORIES.map(c=>`<option ${q.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label>${input('points','نقاط الدرجة الكاملة',q.points,'number','min="0" max="1000"')}${input('min_age','من عمر',q.min_age||4,'number','min="1" max="25"')}${input('max_age','إلى عمر',q.max_age||18,'number','min="1" max="25"')}<label>الأسئلة<textarea name="questions" required>${esc(q.questions.map(x=>[x.text,...x.options,x.correct+1].join(' | ')).join('\n'))}</textarea></label><p class="muted">سطر لكل سؤال: السؤال | الخيار الأول | الثاني | الثالث | رقم الإجابة الصحيحة (1 أو 2 أو 3). مثال: ناتج ٢ + ٢؟ | ٣ | ٤ | ٥ | 2</p><button>حفظ الاختبار</button></form>`);$('#qf').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(+f.get('min_age')>+f.get('max_age'))return note('تحقق من الأعمار');mutate(s=>{const questions=f.get('questions').trim().split('\n').map(line=>{const p=line.split('|').map(x=>x.trim());if(p.length!==5||p.slice(0,4).some(x=>!x)||![1,2,3].includes(+p[4]))throw Error('تحقق من تنسيق الأسئلة ورقم الإجابة');return {text:p[0],options:p.slice(1,4),correct:+p[4]-1}});const row={...q,id:id||uid(),name:f.get('name'),category:f.get('category'),min_age:+f.get('min_age'),max_age:+f.get('max_age'),points:+f.get('points'),questions};if(id)s.quizzes[s.quizzes.findIndex(x=>x.id===id)]=row;else s.quizzes.push(row)})};}
function attemptQuiz(id){const q=state.quizzes.find(q=>q.id===id);if(!q)return;modal(`<h2>${esc(q.name)}</h2><form id="attempt">${isChild()?'<p>إجاباتك تُسجّل في حسابك فقط.</p>':pick()}${q.questions.map((x,i)=>`<label>${esc(x.text)}<select name="q${i}" required><option value="">اختر الإجابة</option>${x.options.map((o,j)=>`<option value="${j}">${esc(o)}</option>`).join('')}</select></label>`).join('')}<button>إنهاء الاختبار</button></form>`);$('#attempt').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;const form=e.target,f=new FormData(form),child=isChild()?membership.child_id:f.get('child'),answers=q.questions.map((_,i)=>+f.get('q'+i));form.querySelector('button').disabled=true;try{if(mode==='demo'){const next=structuredClone(state);submitQuiz(next,child,id,answers,today(),uid());validate(next);state=next}else{await refreshToken();await request('/rest/v1/rpc/submit_quiz',{p_quiz:id,p_child:isChild()?null:child,p_answers:answers});await load()}$('#modal').close();render();const row=state.attempts.filter(a=>a.child===child&&a.quiz===id).at(-1);note('أحسنت! نتيجتك '+row.correct+' من '+row.total+'، وحصلت على '+row.points+' نقطة.','success')}catch(e){note(e.message)}finally{busy=false;if(form.isConnected)form.querySelector('button').disabled=false}};}
function reports(){app.innerHTML=`<div class="card"><h2>تقرير إنجازات العائلة</h2><div class="toolbar"><label>الفترة<select id="period"><option value="day">يومي</option><option value="week">أسبوعي</option><option value="month">شهري</option><option value="custom">مخصص</option></select></label>${input('start','من',today(),'date')}${input('end','إلى',today(),'date')}<label>الطفل<select id="reportChild"><option value="">كل الأطفال</option>${options()}</select></label><label>نوع السجل<select id="reportKind"><option value="">كل الأنواع</option><option value="achievement">إنجاز</option><option value="game">لعبة</option><option value="quiz">اختبار</option><option value="bonus">نقاط تشجيعية</option><option value="deduction">خصم</option><option value="reward">استبدال مكافأة</option></select></label><label>المعيار<select id="reportCriterion"><option value="">كل المعايير</option>${state.criteria.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('')}</select></label><label>بحث<input id="reportSearch" type="search" placeholder="الإنجاز أو الملاحظة"></label><button id="clearReport" class="secondary">مسح الفلاتر</button><button id="print">طباعة</button></div><div id="report"></div></div>`;const draw=()=>{const start=$('[name=start]').value,end=$('[name=end]').value,child=$('#reportChild').value,kind=$('#reportKind').value,criterion=$('#reportCriterion').value,q=$('#reportSearch').value;if(start>end){$('#report').textContent='تاريخ البداية يجب أن يسبق النهاية';return}const all=[...(state.adjustments||[]).map(e=>({...e,kind:'deduction'})),...state.evaluations.map(e=>({...e,kind:'achievement',name:state.criteria.find(c=>c.id===e.criterion)?.name||'معيار سابق'})),...state.attempts.map(e=>({...e,kind:e.kind==='bonus'?'bonus':isGameAttempt(e)?'game':'quiz',note:e.kind==='bonus'?e.note:`${e.correct} / ${e.total} إجابات صحيحة`})),...state.redemptions.map(r=>({...r,points:-r.cost,kind:'reward',note:'استبدال معتمد'}))];const rows=all.filter(e=>(!criterion||e.criterion===criterion)&&matchesFilters({...e,text:e.name+' '+(e.note||'')},{child,kind,from:start,to:end,q})).sort((a,b)=>b.date.localeCompare(a.date));$('#report').innerHTML=`<p>الفترة: ${esc(start)} — ${esc(end)} · ${rows.length} سجل مطابق</p><div class="grid">${state.children.filter(c=>!child||c.id===child).map(c=>{const list=rows.filter(r=>r.child===c.id);return `<div><b>${esc(c.name)}</b><p>صافي السجلات المعروضة: ${list.reduce((sum,r)=>sum+r.points,0)} نقطة<br>المستبدل ضمن التصفية: ${list.filter(r=>r.kind==='reward').reduce((sum,r)=>sum+r.cost,0)} نقطة<br>الرصيد الحالي لجميع السجلات: ${balance(state,c.id)} نقطة</p></div>`}).join('')}</div><div class="table-wrap"><table><thead><tr><th>التاريخ</th><th>الطفل</th><th>الإنجاز / العملية</th><th>النقاط</th><th>الملاحظة</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.date)}</td><td>${esc(state.children.find(c=>c.id===r.child)?.name)}</td><td>${esc(r.name)}</td><td>${r.points}</td><td>${esc(r.note)}</td></tr>`).join('')||'<tr><td colspan="5">لا توجد سجلات مطابقة.</td></tr>'}</tbody></table></div>`};$('#period').onchange=()=>{const p=$('#period').value,d=today();$('[name=end]').value=d;$('[name=start]').value=p==='week'?weekStart():p==='month'?d.slice(0,8)+'01':d;draw()};$('[name=start]').onchange=$('[name=end]').onchange=()=>{$('#period').value='custom';draw()};$('#reportChild').onchange=$('#reportKind').onchange=$('#reportCriterion').onchange=$('#reportSearch').oninput=draw;$('#clearReport').onclick=()=>{$('#period').value='day';$('[name=start]').value=$('[name=end]').value=today();$('#reportChild').value=$('#reportKind').value=$('#reportCriterion').value=$('#reportSearch').value='';draw()};$('#print').onclick=()=>window.print();draw();}

async function syncScreen(){if(busy)return;try{if(mode==='cloud')await load();render();note('تم تحديث البيانات.','success')}catch(e){note(e.message)}}
function requestRows(parent=false,rows=pointRequests){return rows.map(r=>{const c=state.criteria.find(c=>c.id===r.criterion_id),child=state.children.find(c=>c.id===r.child_id);return `<article class="card" data-filter-item data-filter-child="${esc(r.child_id)}" data-filter-status="${esc(r.status)}" data-filter-date="${esc(r.day)}" data-filter-kind="achievement" data-request-id="${esc(r.id)}"><div class="row between"><h3>${esc(c?.name||'معيار سابق')}</h3><span class="badge status-${r.status}">${c?.archived&&r.status==='rejected'?'المعيار محذوف':({pending:'بانتظار الموافقة',approved:'معتمد ✓',rejected:'مرفوض — يمكن تعديله أو حذفه'}[r.status]||'')}</span></div>${parent?`<p>الطفل: ${esc(child?.name)}</p>`:''}<p>${esc(r.day)} · ${esc(levelLabels(c)[r.level])} · النقاط المقترحة: ${c?.points[r.level]??'—'}</p><p>${esc(r.note)}</p>${evidenceMarkup(r.evidence,esc)}${r.review_note?`<p class="muted">رد ولي الأمر: ${esc(r.review_note)}</p>`:''}${parent&&r.status==='pending'?`<button data-review="${r.id}">مراجعة الطلب</button>`:''}${!parent&&r.status==='rejected'&&!c?.archived?`<a class="button secondary" href="#daily?request=${encodeURIComponent(r.id)}">${r.status==='approved'?'طلب تعديل الإنجاز':'تعديل وإعادة إرسال'}</a>`:''}${r.status==='rejected'?`<button class="danger" data-delete-rejected="${r.id}">حذف الطلب المرفوض</button>`:''}</article>`}).join('')||'<div class="card empty">لا توجد طلبات بعد.</div>'}
function bindRejectedDeletes(){document.querySelectorAll('[data-delete-rejected]').forEach(b=>b.onclick=()=>{const r=pointRequests.find(r=>r.id===b.dataset.deleteRejected);if(!r||r.status!=='rejected')return;modal(`<h2>حذف طلب الإنجاز المرفوض</h2><p>${esc(state.criteria.find(c=>c.id===r.criterion_id)?.name||'إنجاز سابق')} · ${esc(r.day)}</p><p>سيختفي الطلب من قوائم الطفل وولي الأمر. يبقى أي تقييم معتمد سابق ونقاطه محفوظًا، ويمكن إرسال طلب جديد للمهمة لاحقًا إذا سمح حدها اليومي.</p><form id="deleteRejectedRequest"><button class="danger">تأكيد حذف الطلب</button></form>`);$('#deleteRejectedRequest').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;const button=e.target.querySelector('button');button.disabled=true;try{if(mode==='demo'){const current=pointRequests.find(x=>x.id===r.id);if(!current||current.status!=='rejected')throw Error('تغيرت حالة الطلب؛ حدّث القائمة');pointRequests=pointRequests.filter(x=>x.id!==r.id)}else{await refreshToken();await request('/rest/v1/rpc/delete_rejected_point_request',{p_id:r.id});await load()}$('#modal').close();$('#modalBody').replaceChildren();render();note('تم حذف الطلب المرفوض من القائمة مع حفظ النقاط المعتمدة.','success')}catch(error){if(mode==='cloud'&&error.status===409){try{await load()}catch{}}note(error.message)}finally{busy=false;if(button.isConnected)button.disabled=false}}})}
function childPointDetails(){if(!isChild())return;const id=membership.child_id,child=state.children.find(c=>c.id===id);if(!child)return;const rows=pointDetails(state,id);const types={achievement:'إنجاز',game:'لعبة',quiz:'اختبار',bonus:'نقاط تشجيعية',deduction:'خصم',reward:'استبدال مكافأة'};const original=rows.filter(r=>r.points>0).reduce((sum,r)=>sum+r.points,0),deductions=-rows.filter(r=>r.kind==='deduction').reduce((sum,r)=>sum+r.points,0),spent=-rows.filter(r=>r.kind==='reward').reduce((sum,r)=>sum+r.points,0);app.innerHTML=`<div class="row between"><h2>تفاصيل نقاطي — ${esc(child.name)}</h2><button id="ledgerSync" class="secondary">تحديث نقاطي</button></div><div class="grid"><div class="card"><h3>نقاطي الأصلية</h3><b class="number">${original}</b></div><div class="card"><h3>الخصومات المسجلة</h3><b class="number">${deductions}</b></div><div class="card"><h3>المستبدل بمكافآت</h3><b class="number">${spent}</b></div><div class="card"><h3>رصيدي المتبقي</h3><b class="number">${balance(state,id)}</b></div></div><p class="muted">الملخص لإجمالي نقاطك الحالية. الفلاتر أدناه تخص تفاصيل العمليات المعروضة. الطلبات المعلقة والمرفوضة لا تغيّر رصيدك.</p><section id="childLedgerRows" data-filter-scope="${esc(id)}"><div class="grid">${rows.map(r=>`<article class="card" data-filter-item data-filter-kind="${r.kind}" data-filter-date="${esc(r.date)}"><div class="row between"><h3>${esc(r.name)}</h3><span class="score">${r.points>0?'+':''}${r.points} نقطة</span></div><p>${types[r.kind]} · ${esc(r.date)}</p><p>${r.kind==='deduction'?'سبب الخصم: ':''}${esc(r.note||'لم يُسجل سبب')}</p>${evidenceMarkup(r.evidence,esc)}</article>`).join('')||'<p>لم تُسجل عمليات نقاط بعد.</p>'}</div></section><a href="#deductions" class="button secondary">بنود الخصم وقيمة كل بند</a>`;$('#ledgerSync').onclick=syncScreen;installListFilters($('#childLedgerRows'),{esc,kinds:Object.entries(types).map(([id,name])=>({id,name}))});}
function childDeductionSummary(){const deductions=(state.adjustments||[]).filter(r=>r.child===membership.child_id).slice().reverse();const rules=(state.deductionRules||[]).filter(r=>!r.archived);return `<section class="card"><div class="row between"><h2>بنود الخصم وقيمتها</h2><a href="#deductions" class="button secondary">عرض جميع البنود</a></div><p class="muted">هذه قيم الحالات المتفق عليها؛ الخصم يُسجل عندما يؤكده ولي الأمر.</p>${rules.length?`<div class="table-wrap"><table><thead><tr><th>البند</th><th>قيمة الخصم</th></tr></thead><tbody>${rules.map(r=>`<tr><td>${esc(r.name)}${r.description?`<br><small>${esc(r.description)}</small>`:''}</td><td>− ${r.points} نقطة</td></tr>`).join('')}</tbody></table></div>`:'<p>لم يحدد ولي الأمر بنود خصم بعد.</p>'}${deductions.length?`<h3>الخصومات المسجلة عليّ</h3>${deductions.slice(0,10).map(r=>`<article class="task"><b>${r.points} نقطة · ${esc(r.date)}</b><p>سبب الخصم: ${esc(r.note||'لم يُسجل سبب')}</p></article>`).join('')}<a href="#ledger">عرض جميع التفاصيل</a>`:''}</section>`;}
function childHome(){const child=state.children.find(c=>c.id===membership.child_id);if(!child){app.innerHTML='<div class="card">ملف الطفل غير مرتبط. تواصل مع ولي الأمر.</div>';return}app.innerHTML=`<div class="hero"><span class="plant">${features.avatar(child)}</span><h2>أهلًا ${esc(child.name)}! 🌟</h2><a href="#ledger" class="button secondary">▤ تفاصيل نقاطي</a><p>أنجز، أخبرنا، واحتفل بما تعلمته. نقاط الطلب تظهر في رصيدك بعد موافقة ولي الأمر.</p><a href="#daily" class="button secondary">+ أضف إنجازًا (صورة اختيارية)</a> <button id="childCustomize" class="secondary">🎨 صورتي ولون سيارتي</button> <a href="#quizzes" class="button secondary">✎ الاختبارات والتحديات</a> <a href="#games" class="button secondary">🎮 ألعاب العائلة</a></div><div class="grid">${childCard(child)}<div class="card"><h3>إنجازاتي تنتظر التشجيع</h3><div class="number">${pointRequests.filter(r=>r.status==='pending').length}</div><p>طلبات بانتظار موافقة ولي الأمر</p><button id="childSync" class="secondary">تحديث الإنجازات</button></div></div>${childDeductionSummary()}${assessmentPanel(child)}<div class="card"><h2>إنجازاتي المعتمدة</h2>${[...state.evaluations,...state.attempts.filter(isGameAttempt),...(state.adjustments||[])].map(e=>`<p>⭐ ${e.points} · ${esc(e.name||state.criteria.find(c=>c.id===e.criterion)?.name)} · ${esc(e.date)}<br><small>${esc(e.note)}</small></p>${evidenceMarkup(e.evidence,esc)}`).join('')||'ستظهر هنا إنجازاتك بعد اعتمادها.'}</div><div class="card encouragement-card"><h2>رسائل تشجيعي 💚</h2>${(state.encouragements||[]).slice(-20).reverse().map(e=>`<p>💚 ${esc(e.note)} · ${esc(e.date)}</p>`).join('')||'رسالة تشجيعك القادمة هنا.'}</div><h2>متابعة طلباتي</h2><div class="grid">${requestRows()}</div>`;bindRejectedDeletes();$('#childCustomize').onclick=features.customizeChild;$('#childSync').onclick=syncScreen;bindProfiles();bindAssessmentPanel(child);}
function childRequests(){const seed=pointRequests.find(r=>r.id===new URLSearchParams(location.hash.split('?')[1]||'').get('request')&&r.child_id===membership.child_id);app.innerHTML=`<div class="row between"><h2>أخبرنا عن إنجازك ☀</h2><button id="requestSync" class="secondary">تحديث</button></div><div class="card"><form id="sendRequest"><label>ماذا أنجزت؟<select name="criterion" required>${state.criteria.filter(c=>!c.archived&&(!isChild()||!c.assigned_child||c.assigned_child===membership.child_id)).map(c=>`<option value="${c.id}" ${seed?.criterion_id===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label>${input('day','متى أنجزته؟',seed?.day||today(),'date','max="'+today()+'"')}<label>كيف أنجزته؟<select name="level"></select></label><p id="estimated" class="score"></p><p id="submissionStatus" role="status"></p><p id="submissionCountdown" class="score"></p><label>احكِ لنا عن محاولتك<textarea name="note" maxlength="300" placeholder="قرأت قصة جديدة اليوم…"></textarea></label>${evidenceFields()}<button type="submit">إرسال لولي الأمر</button><p class="muted">الطلب لا يضيف نقاطًا حتى يعتمد ولي الأمر الإنجاز. الإنجاز مرة واحدة يوميًا افتراضيًا، أو حسب حد التكرار الذي يحدده ولي الأمر في المعيار. يمكن تصحيح الطلب المرفوض من زر التعديل.</p></form></div><p><a href="#requests">عرض سجل طلباتي وحالات الموافقة ←</a></p>`;$('#requestSync').onclick=syncScreen;const form=$('#sendRequest');let proof=bindEvidence(form,'',note),correction=null;const estimate=()=>{const criterion=form.elements.criterion.value,day=form.elements.day.value;$('#estimated').textContent='النقاط المقترحة: '+(state.criteria.find(c=>c.id===criterion)?.points[+form.elements.level.value]??0)+' ⭐';const window=submissionWindow(state,membership.child_id,criterion);$('#submissionCountdown').textContent=window.text;const status=submissionStatus(state,pointRequests,membership.child_id,criterion,day,correction);$('#submissionStatus').textContent=window.blocked?'':status.text;form.querySelector('button[type=submit]').disabled=status.blocked||!criterion;form.querySelector('button[type=submit]').textContent=status.revision?'إرسال طلب تعديل لولي الأمر':'إرسال لولي الأمر';};const levelOptions=()=>{const c=state.criteria.find(c=>c.id===form.elements.criterion.value);form.elements.level.innerHTML=levelLabels(c).map((label,i)=>`<option value="${i}" ${i===2&&!c?.labels?'selected':''}>${esc(label)}</option>`).join('');const prior=seed&&seed.status==='rejected'&&seed.criterion_id===form.elements.criterion.value&&seed.day===form.elements.day.value?seed:null;correction=prior?.id||null;if(prior){form.elements.level.value=String(prior.level);form.elements.note.value=prior.note||''}else form.elements.note.value='';form.querySelector('.evidence-input').outerHTML=evidenceFields();proof=bindEvidence(form,prior?.evidence||'',note);estimate()};form.elements.criterion.onchange=form.elements.day.onchange=levelOptions;form.elements.level.onchange=estimate;levelOptions();const countdown=setInterval(()=>{if(!form.isConnected){clearInterval(countdown);return}estimate()},1000);form.onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;const button=form.querySelector('button[type=submit]');button.disabled=true;try{const f=new FormData(form),evidence=await proof();const status=submissionStatus(state,pointRequests,membership.child_id,f.get('criterion'),f.get('day'),correction);if(status.blocked)throw Error(status.text);if(mode==='demo'){const criterion=f.get('criterion'),day=f.get('day');const old=correction?pointRequests.find(r=>r.id===correction&&r.status==='rejected'):null;const occurrence=old?.occurrence||Math.max(0,...pointRequests.filter(r=>r.child_id===membership.child_id&&r.criterion_id===criterion&&r.day===day).map(r=>r.occurrence||1),...state.evaluations.filter(e=>e.child===membership.child_id&&e.criterion===criterion&&e.date===day).map(e=>e.occurrence||1))+1;const row={id:old?.id||uid(),child_id:membership.child_id,criterion_id:criterion,day,level:+f.get('level'),note:f.get('note'),evidence,occurrence,status:'pending'};if(old)Object.assign(old,row);else pointRequests.push(row);location.hash='requests';render();note('تم إرسال الطلب في التجربة. انتقل إلى ولي الأمر لاعتماده.','success');return}await refreshToken();await request('/rest/v1/rpc/submit_achievement',{p_criterion:f.get('criterion'),p_day:f.get('day'),p_level:+f.get('level'),p_note:f.get('note'),p_evidence:evidence,p_request:correction});location.hash='requests';await load();render();note('تم إرسال طلبك بنجاح! سيظهر التعديل في إنجازاتك بعد موافقة ولي الأمر.','success')}catch(e){if(e.status===409&&mode==='cloud'){try{await load()}catch{}}note(e.message)}finally{busy=false;if(form.isConnected)estimate()}};}
function childHistory(){app.innerHTML=`<div class="row between"><h2>سجل طلبات النقاط</h2><button id="historySync" class="secondary">تحديث الطلبات</button></div><p class="muted">تابع هنا طلباتك المعلّقة والمعتمدة والمعادة للمراجعة. الطلب المعلّق لا يضيف نقاطًا إلى رصيدك.</p><a class="button" href="#daily">+ إضافة إنجاز</a><div class="grid">${requestRows()}</div>`;$('#historySync').onclick=syncScreen;bindRejectedDeletes();installListFilters(app,{esc,children:state.children,statuses:true});}
function reviewAllPending(button){if(!isParent(membership))return;const kind=button.dataset.reviewBatchKind,approve=button.dataset.batchApprove==='true',cards=[...app.querySelectorAll('[data-filter-item]')].filter(x=>!x.hidden&&x.dataset.filterKind===kind&&x.dataset.filterStatus==='pending'),ids=cards.map(x=>x.dataset.requestId);if(!ids.length)return note('لا توجد طلبات معلقة ظاهرة تطابق الفلتر');if(ids.length>200)return note('حدد فترة أقصر؛ الحد الأقصى ٢٠٠ طلب');modal(`<h2>${approve?'قبول':'رفض'} جميع ${kind==='game'?'نقاط الألعاب':'طلبات الاستبدال'} الظاهرة</h2><p>${ids.length} طلبًا حسب الفلتر الحالي.${approve&&kind==='reward'?' ستُخصم التكلفة المعتمدة من أرصدة الأطفال بعد التحقق منها.':''}</p><ul>${cards.map(c=>`<li>${esc(c.querySelector('h3')?.textContent||'طلب')} · ${esc(c.dataset.filterDate)}</li>`).join('')}</ul><form id="reviewAllPending"><label>رسالة اختيارية<textarea name="note" maxlength="300"></textarea></label><button ${approve?'':'class="danger"'}>تأكيد ${approve?'قبول':'رفض'} الجميع</button></form>`);$('#reviewAllPending').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;try{const text=new FormData(e.target).get('note');if(mode==='demo'){if(kind==='game')await games.demoGameBatch(ids,approve,text);else features.demoRewardBatch(ids,approve,text)}else{await refreshToken();await request('/rest/v1/rpc/review_pending_batch',{p_kind:kind,p_ids:ids,p_approve:approve,p_note:text});await load()}$('#modal').close();render();note('تم '+(approve?'قبول':'رفض')+' الطلبات الظاهرة بنجاح.','success')}catch(error){note(error.message)}finally{busy=false}};}
document.addEventListener('click',e=>{const b=e.target.closest('[data-review-batch-kind]');if(b)reviewAllPending(b)});
function bindBulkReviews(){document.querySelectorAll('[data-bulk-child]').forEach(b=>b.onclick=()=>{const ids=[...document.querySelectorAll('[data-filter-item]')].filter(x=>!x.hidden&&x.dataset.filterChild===b.dataset.bulkChild&&x.dataset.filterKind==='achievement'&&x.dataset.filterStatus==='pending').map(x=>x.dataset.requestId),rows=pointRequests.filter(r=>ids.includes(r.id));if(!rows.length)return note('لا توجد طلبات معلقة مطابقة للفلتر');if(rows.length>200)return note('حدد فترة أقصر بالفلتر؛ الحد الأقصى ٢٠٠ طلب في الدفعة.');const child=state.children.find(c=>c.id===b.dataset.bulkChild);modal(`<h2>اعتماد إنجازات ${esc(child?.name)}</h2><p>سيُعتمد ${rows.length} طلبًا ظاهرًا حسب الفلتر، بالمستويات المقترحة.</p><ul>${rows.map(r=>`<li>${esc(state.criteria.find(c=>c.id===r.criterion_id)?.name)} · ${esc(r.day)} · ${state.criteria.find(c=>c.id===r.criterion_id)?.points[r.level]??0} نقطة</li>`).join('')}</ul><form id="bulkReview"><label>رسالة تشجيع اختيارية<textarea name="note" maxlength="300"></textarea></label><button>تأكيد اعتماد جميع الطلبات المعروضة</button></form>`);$('#bulkReview').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;try{const noteText=new FormData(e.target).get('note');if(mode==='demo'){const next=structuredClone(state);for(const r of rows){if(r.status!=='pending')throw Error('تغيرت حالة طلب؛ حدّث القائمة');evaluate(next,{child:r.child_id,criterion:r.criterion_id,date:r.day,level:r.level,note:r.note,evidence:r.evidence,occurrence:r.occurrence||1})}validate(next);state=next;for(const r of rows){r.status='approved';r.review_note=noteText;if(noteText.trim())(state.encouragements??=[]).push({id:uid(),child:r.child_id,note:noteText.trim(),date:today(),request_id:r.id})}}else{await refreshToken();await request('/rest/v1/rpc/approve_child_achievements',{p_child:b.dataset.bulkChild,p_ids:ids,p_note:noteText});await load()}$('#modal').close();render();note('تم اعتماد إنجازات الطفل وتحديث نقاطه.','success')}catch(error){note(error.message)}finally{busy=false}}})}
function reviewRequests(){app.innerHTML=`<div class="row between"><h2>طلبات النقاط من أطفالي</h2>${quickButtons()}<button id="reviewSync" class="secondary">تحديث الطلبات</button></div><p class="muted">الإنجاز مرة واحدة يوميًا افتراضيًا، أو حسب حد التكرار في المعيار. كل مرة معتمدة تُحتسب بسجل مستقل؛ لا يمكن للطفل إعادة إرسال الطلب المعلّق أو المعتمد.</p><section id="achievementGroups">${state.children.map(c=>{const rows=pointRequests.filter(r=>r.child_id===c.id);return rows.length?`<section class="card" data-filter-group><div class="row between"><h2>${esc(c.name)}</h2><button data-bulk-child="${esc(c.id)}">اعتماد إنجازات الطفل المعلقة</button></div><div class="grid">${requestRows(true,rows)}</div></section>`:''}).join('')||'<p>لا توجد طلبات إنجاز.</p>'}</section><section id="rewardApprovals" data-filter-group></section><details class="card" id="gameApprovalToggle" data-filter-group><summary>اعتماد نقاط الألعاب 🎮 — اضغط للعرض</summary><section id="gameApprovals"></section></details>`;$('#reviewSync').onclick=syncScreen;bindBulkReviews();bindRejectedDeletes();document.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>{const r=pointRequests.find(r=>r.id===b.dataset.review),c=state.criteria.find(c=>c.id===r.criterion_id);modal(`<h2>مراجعة إنجاز الطفل</h2><p>${esc(r.note)}</p>${evidenceMarkup(r.evidence,esc)}<form id="reviewForm"><label>المستوى المعتمد<select name="level">${levelLabels(c).map((t,i)=>`<option value="${i}" ${r.level===i?'selected':''}>${t} (${c?.points[i]??0} نقطة)</option>`).join('')}</select></label>${encouragementFields(esc)}<div class="row"><button name="action" value="approve">اعتماد الإنجاز</button><button name="action" value="reject" class="danger">رفض الطلب</button></div></form>`);bindEncouragement($('#reviewForm'),{esc,request,refreshToken,note,mode});$('#reviewForm').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;try{const f=new FormData(e.target);if(mode==='demo'){if(r.status!=='pending')throw Error('تمت مراجعة الطلب');if(e.submitter.value==='approve'){evaluate(state,{child:r.child_id,criterion:r.criterion_id,date:r.day,level:+f.get('level'),note:r.note,evidence:r.evidence,occurrence:r.occurrence||1});if(f.get('note').trim())(state.encouragements??=[]).push({id:uid(),child:r.child_id,note:f.get('note').trim(),date:today(),request_id:r.id});r.status='approved'}else r.status='rejected';r.review_note=f.get('note');$('#modal').close();render();note(e.submitter.value==='reject'?'تم رفض الطلب. يمكنك الآن حذفه من بطاقته، أو يراجعه الطفل ويعيد إرساله.':'تم اعتماد الإنجاز في التجربة المؤقتة.','success');return}await refreshToken();await request('/rest/v1/rpc/review_point_request',{p_id:r.id,p_approve:e.submitter.value==='approve',p_level:+f.get('level'),p_note:f.get('note')});await load();$('#modal').close();render();note(e.submitter.value==='reject'?'تم رفض الطلب. يمكنك الآن حذفه من بطاقته، أو يراجعه الطفل ويعيد إرساله.':'تم اعتماد الإنجاز وتحديث النقاط.','success')}catch(e){note(e.message)}finally{busy=false}}});games.showApprovals('#gameApprovals');features.rewardApprovals('#rewardApprovals');installListFilters(app,{esc,children:state.children,statuses:true,kinds:[{id:'achievement',name:'إنجاز'},{id:'reward',name:'استبدال مكافأة'},{id:'game',name:'لعبة'}]});}
async function accounts(){return features.accounts()}
function pointsPage(){if(!can(membership,'deduct_points')){app.innerHTML='<div class="card"><p>تصفير النقاط من مساحة الطفل ← زر تصفير جميع نقاط الطفل.</p></div>';return}app.innerHTML=`<div class="card"><h2>خصم النقاط</h2><p>تظهر العمليات التي منحك المدير صلاحيتها فقط. يُسجّل السبب ويظهر للطفل، يمكن أن يصبح الرصيد سالبًا إذا تجاوز الخصم النقاط المتاحة. اختر خصمًا بسيطًا ومتناسبًا مع السلوك.</p><form id="pointsForm">${pick()}<p id="currentBalance" class="score"></p><label>العملية<select name="action">${can(membership,'deduct_points')?'<option value="deduct">خصم نقاط</option>':''}</select></label><label>المهمة<select name="criterion"><option value="">عام / جميع المهام عند التصفير</option>${state.criteria.filter(c=>!c.archived&&(!isChild()||!c.assigned_child||c.assigned_child===membership.child_id)).map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><div id="deductionAmount"><label>بند الخصم<select name="rule"><option value="">خصم مخصص مع سبب</option>${(state.deductionRules||[]).filter(r=>!r.archived).map(r=>`<option value="${r.id}">${esc(r.name)} (− ${r.points} نقطة)</option>`).join('')}</select></label><a href="#deductions">إدارة بنود الخصم</a>${input('amount','قيمة الخصم',1,'number','min="1" max="1000"')}</div><label>السبب<textarea name="reason" required maxlength="300" placeholder="سبب واضح يفهمه الطفل…"></textarea></label><div id="resetWarning" hidden><p>تصفير مهمة: أرشفة نقاطها وخصوماتها وطلباتها فقط. تصفير جميع المهام: أرشفة كل نقاط الطفل وخصوماته واستبدالاته وطلباته، وإعادة رصيده إلى صفر. تبقى ملفات الأطفال والحسابات.</p><label>اكتب «تصفير» للتأكيد<input name="confirmation" autocomplete="off"></label></div><button class="danger">تنفيذ العملية</button></form></div><div class="card"><h2>مقترح تحويل النقاط إلى مكافآت</h2><p>كل ١ نقطة = نجمة واحدة. اجعل المكافآت اختيارية ومتفقًا عليها، ويمكن تعديل تكلفتها من «المكافآت».</p><table><tr><th>النقاط</th><th>مكافأة مقترحة</th></tr><tr><td>٢٠</td><td>اختيار قصة المساء أو لعبة عائلية</td></tr><tr><td>٥٠</td><td>نشاط خاص مع أحد الوالدين لمدة ٣٠ دقيقة</td></tr><tr><td>١٠٠</td><td>اختيار نزهة عائلية بسيطة</td></tr></table><p class="muted">اقتراح للخصم: مخالفة بسيطة ١–٢ نقطة، وسلوك متكرر بعد التذكير ٣–٥ نقاط. لا تستخدم التصفير كعقوبة؛ هو لتنظيف التجربة. هذه مقترحات فقط ولا تُنشئ مكافآت تلقائيًا.</p></div><div class="card"><h2>سجل الخصومات والتصفير</h2>${(state.adjustments||[]).map(a=>`<p>${esc(state.children.find(c=>c.id===a.child)?.name)} · <b>${a.points}</b> · ${esc(a.date)} · سبب الخصم: ${esc(a.note||'لم يُسجل سبب')}</p>`).join('')||'<p>لا توجد خصومات.</p>'}${(state.resetArchive||[]).map(a=>`<p>تصفير ${esc(a.criterion?state.criteria.find(c=>c.id===a.criterion)?.name:'كل النقاط')} · ${esc(state.children.find(c=>c.id===a.child)?.name)} · ${esc(a.date)} · ${esc(a.note)}</p>`).join('')}<p class="muted">السجلات المؤرشفة محفوظة ضمن النسخة الاحتياطية؛ لا يوجد زر استعادة تلقائي في هذه النسخة.</p></div>`;const form=$('#pointsForm');if(selected&&state.children.some(c=>c.id===selected))form.elements.child.value=selected;const update=()=>{const reset=form.elements.action.value==='reset',usingRule=!reset&&!!form.elements.rule.value;form.elements.criterion.closest('label').hidden=usingRule;form.elements.criterion.disabled=usingRule;form.elements.reason.maxLength=usingRule?180:300;$('#deductionAmount').hidden=reset;form.elements.amount.required=!reset;$('#resetWarning').hidden=!reset;form.elements.confirmation.required=reset;$('#currentBalance').textContent='الرصيد المتاح: '+balance(state,form.elements.child.value)+' نقطة';form.querySelector('button').disabled=!form.elements.child.value;};form.elements.action.onchange=form.elements.child.onchange=update;const chooseRule=()=>{const r=(state.deductionRules||[]).find(r=>r.id===form.elements.rule.value&&!r.archived);form.elements.amount.readOnly=!!r;if(r)form.elements.amount.value=r.points;update()};form.elements.rule.onchange=chooseRule;const initialRule=new URLSearchParams(location.hash.split('?')[1]||'').get('rule');if(initialRule&&can(membership,'deduct_points')){form.elements.action.value='deduct';form.elements.rule.value=initialRule;chooseRule()}update();form.onsubmit=async e=>{e.preventDefault();if(busy)return;const f=new FormData(form);if(!can(membership,f.get('action')==='reset'?'reset_points':'deduct_points'))return note('لا تملك صلاحية هذه العملية');if(f.get('action')==='reset'&&f.get('confirmation').trim()!=='تصفير')return note('اكتب كلمة تصفير لتأكيد العملية');busy=true;form.querySelector('button').disabled=true;try{if(mode==='demo'){const next=structuredClone(state);if(f.get('action')==='deduct'){const rule=(state.deductionRules||[]).find(r=>r.id===f.get('rule')&&!r.archived);deduct(next,f.get('child'),f.get('criterion'),rule?rule.points:+f.get('amount'),rule?rule.name+' — '+f.get('reason'):f.get('reason'),uid(),today());}else{resetPoints(next,f.get('child'),f.get('criterion'),uid(),today(),f.get('reason'));pointRequests=pointRequests.filter(r=>r.child_id!==f.get('child')||(f.get('criterion')&&r.criterion_id!==f.get('criterion')))}validate(next);state=next;}else{await refreshToken();if(f.get('action')==='deduct'&&f.get('rule'))await request('/rest/v1/rpc/apply_deduction_rule',{p_child:f.get('child'),p_rule:f.get('rule'),p_note:f.get('reason'),p_revision:revision});else await request('/rest/v1/rpc/manage_points',{p_child:f.get('child'),p_action:f.get('action'),p_criterion:f.get('criterion')||null,p_amount:f.get('action')==='deduct'?+f.get('amount'):0,p_reason:f.get('reason'),p_revision:revision});await load();}render();note(f.get('action')==='deduct'?'تم خصم النقاط وتسجيل السبب بنجاح.':'تم تصفير النقاط المحددة وأرشفة سجلاتها بنجاح.','success')}catch(e){note(e.message)}finally{busy=false;if(form.isConnected)form.querySelector('button').disabled=false}};}
function bindProfiles(){bindQuickActions();document.querySelectorAll('[data-points]').forEach(b=>b.onclick=()=>{selected=b.dataset.points;location.hash='points';render()});document.querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>profile(b.dataset.profile))}
